import {targetAt} from '../shared.mjs';
export function observe(s) {
 const h=s.history.slice(-3), available=!s.observationMissing;
 return {episodeId:s.episodeId,revision:s.revision,round:s.round,health:s.health,supplies:s.supplies,charge:s.charge,budget:s.budget,lastKind:s.history.at(-1)?.kind??null,recentDamage:h.map(e=>e.damage),recentMoves:h.map(e=>e.move),pressure:available&&h.length===3?.6*(12-s.health)/12+.4*Math.min(1,h.reduce((n,e)=>n+e.damage,0)/6):null,target:targetAt(s.profile,s.round,s.targetSchedule),flags:{historyComplete:h.length===3,available}};
}
